dashboard.definition:
{
  "title": "AD Accounts Overview",
  "description": "Account-hygiene view of Active Directory built on the lookups of the Microsoft Windows Active Directory Objects app (see README for the lookup names/macros to adjust): enabled vs disabled, password-never-expires, locked, expired, stale, privileged and risky configurations. Figures reflect the last refresh of the lookups, not live LDAP.",
  "inputs": {},
  "defaults": {},
  "visualizations": {
    "viz_1": {
      "type": "splunk.singlevalue",
      "title": "User accounts",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "title": "Enabled",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "title": "Disabled",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "title": "Password never expires (enabled)",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "title": "Locked out",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_6": {
      "type": "splunk.singlevalue",
      "title": "Password not required (enabled)",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_7": {
      "type": "splunk.singlevalue",
      "title": "Expired but still enabled",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_8": {
      "type": "splunk.singlevalue",
      "title": "Stale enabled accounts",
      "dataSources": {
        "primary": "ds_8"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
        "underLabel": "no logon for more than adx_stale_days days"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_9": {
      "type": "splunk.singlevalue",
      "title": "Privileged accounts (enabled)",
      "dataSources": {
        "primary": "ds_9"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_10": {
      "type": "splunk.singlevalue",
      "title": "krbtgt password age (days)",
      "dataSources": {
        "primary": "ds_10"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 180
          },
          {
            "value": "#B0413E",
            "from": 180
          }
        ]
      }
    },
    "viz_11": {
      "type": "splunk.singlevalue",
      "title": "Password expired (enabled)",
      "dataSources": {
        "primary": "ds_11"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
        "underLabel": "older than adx_max_pwd_age_days"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_12": {
      "type": "splunk.singlevalue",
      "title": "Password expires within 14 days",
      "dataSources": {
        "primary": "ds_12"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_13": {
      "type": "splunk.singlevalue",
      "title": "Must change password at next logon",
      "dataSources": {
        "primary": "ds_13"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_14": {
      "type": "splunk.singlevalue",
      "title": "Accounts not compliant with password rules",
      "dataSources": {
        "primary": "ds_14"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_15": {
      "type": "splunk.singlevalue",
      "title": "Privileged passwords too old",
      "dataSources": {
        "primary": "ds_15"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_16": {
      "type": "splunk.bar",
      "title": "Password rule violations (enabled accounts)",
      "dataSources": {
        "primary": "ds_16"
      },
      "options": {
        "legendDisplay": "off"
      },
      "description": "Based on UAC flags, password age and privileged membership. AD does not expose password contents: weak, leaked or dictionary passwords need an offline audit (e.g. DSInternals Test-PasswordQuality) or Entra/AD password protection."
    },
    "viz_17": {
      "type": "splunk.table",
      "title": "Accounts not compliant with password rules",
      "dataSources": {
        "primary": "ds_17"
      },
      "options": {
        "count": 10,
        "wrap": true,
        "columnFormat": {
          "privileged": {
            "rowBackgroundColors": "> table | seriesByName(\"privileged\") | matchValue(privilegedColorConfig)"
          }
        }
      },
      "context": {
        "privilegedColorConfig": [
          {
            "match": "YES",
            "value": "#F8BE34"
          }
        ]
      }
    },
    "viz_18": {
      "type": "splunk.table",
      "title": "Passwords expired or expiring within 14 days",
      "dataSources": {
        "primary": "ds_18"
      },
      "options": {
        "count": 10,
        "wrap": true,
        "columnFormat": {
          "status": {
            "rowBackgroundColors": "> table | seriesByName(\"status\") | matchValue(statusColorConfig)"
          }
        }
      },
      "description": "Negative value = days since the password expired (domain maximum password age = macro adx_max_pwd_age_days; fine-grained policies are not taken into account).",
      "context": {
        "statusColorConfig": [
          {
            "match": "EXPIRED",
            "value": "#B0413E"
          },
          {
            "match": "EXPIRING",
            "value": "#F8BE34"
          }
        ]
      }
    },
    "viz_19": {
      "type": "splunk.pie",
      "title": "Enabled vs disabled",
      "dataSources": {
        "primary": "ds_19"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_20": {
      "type": "splunk.pie",
      "title": "Password posture of enabled accounts",
      "dataSources": {
        "primary": "ds_20"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_21": {
      "type": "splunk.column",
      "title": "Password age of enabled accounts",
      "dataSources": {
        "primary": "ds_21"
      },
      "options": {
        "legendDisplay": "off"
      }
    },
    "viz_22": {
      "type": "splunk.column",
      "title": "Last logon of enabled accounts",
      "dataSources": {
        "primary": "ds_22"
      },
      "options": {
        "legendDisplay": "off"
      }
    },
    "viz_23": {
      "type": "splunk.bar",
      "title": "Password never expires - by OU (top 15, enabled)",
      "dataSources": {
        "primary": "ds_23"
      },
      "options": {
        "legendDisplay": "off"
      }
    },
    "viz_24": {
      "type": "splunk.table",
      "title": "Password never expires - enabled accounts",
      "dataSources": {
        "primary": "ds_24"
      },
      "options": {
        "count": 12,
        "wrap": true,
        "columnFormat": {
          "privileged": {
            "rowBackgroundColors": "> table | seriesByName(\"privileged\") | matchValue(privilegedColorConfig)"
          }
        }
      },
      "context": {
        "privilegedColorConfig": [
          {
            "match": "YES",
            "value": "#F8BE34"
          }
        ]
      }
    },
    "viz_25": {
      "type": "splunk.table",
      "title": "Risky account configurations (enabled)",
      "dataSources": {
        "primary": "ds_25"
      },
      "options": {
        "count": 12,
        "wrap": true
      }
    },
    "viz_26": {
      "type": "splunk.table",
      "title": "Accounts expiring in the next 30 days",
      "dataSources": {
        "primary": "ds_26"
      },
      "options": {
        "count": 12,
        "wrap": true
      }
    },
    "viz_27": {
      "type": "splunk.table",
      "title": "Enabled accounts past their expiry date",
      "dataSources": {
        "primary": "ds_27"
      },
      "options": {
        "count": 8,
        "wrap": true
      }
    },
    "viz_28": {
      "type": "splunk.table",
      "title": "Disabled accounts that still belong to a privileged group",
      "dataSources": {
        "primary": "ds_28"
      },
      "options": {
        "count": 8,
        "wrap": true
      }
    },
    "viz_29": {
      "type": "splunk.table",
      "title": "Stale enabled accounts (oldest logon first)",
      "dataSources": {
        "primary": "ds_29"
      },
      "options": {
        "count": 8,
        "wrap": true
      }
    },
    "viz_30": {
      "type": "splunk.line",
      "title": "Daily trend (needs the \"AD KPI Snapshot\" saved search enabled)",
      "dataSources": {
        "primary": "ds_30"
      },
      "options": {
        "legendDisplay": "bottom"
      },
      "description": "History is built by the disabled-by-default saved search \"AD - KPI Snapshot to Summary Index\". Enable it to see how these figures evolve."
    },
    "viz_31": {
      "type": "splunk.bar",
      "title": "Computers by operating system (top 10)",
      "dataSources": {
        "primary": "ds_31"
      },
      "options": {
        "legendDisplay": "off"
      }
    },
    "viz_32": {
      "type": "splunk.singlevalue",
      "title": "Stale enabled computers",
      "dataSources": {
        "primary": "ds_32"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "User accounts",
      "options": {
        "query": "| `adx_users` | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Enabled",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Disabled",
      "options": {
        "query": "| `adx_users` | where is_disabled=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "Password never expires (enabled)",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND pwd_never_expires=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Locked out",
      "options": {
        "query": "| `adx_users` | where is_locked=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Password not required (enabled)",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND pwd_not_required=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Expired but still enabled",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND is_expired=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Stale enabled accounts",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND days_since_logon>`adx_stale_days` | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_9": {
      "type": "ds.search",
      "name": "Privileged accounts (enabled)",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND is_privileged=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_10": {
      "type": "ds.search",
      "name": "krbtgt password age (days)",
      "options": {
        "query": "| `adx_users` | where sam=\"krbtgt\" | stats max(pwd_age_days) as age",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_11": {
      "type": "ds.search",
      "name": "Password expired (enabled)",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND pwd_expired=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_12": {
      "type": "ds.search",
      "name": "Password expires within 14 days",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND isnotnull(pwd_days_left) AND pwd_days_left>=0 AND pwd_days_left<=14 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_13": {
      "type": "ds.search",
      "name": "Must change password at next logon",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND must_change_pwd=1 | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_14": {
      "type": "ds.search",
      "name": "Accounts not compliant with password rules",
      "options": {
        "query": "| `adx_users` | `adx_pwd_violations` | where isnotnull(violations) | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_15": {
      "type": "ds.search",
      "name": "Privileged passwords too old",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND is_privileged=1 AND pwd_age_days>`adx_priv_max_pwd_age_days` | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_16": {
      "type": "ds.search",
      "name": "Password rule violations (enabled accounts)",
      "options": {
        "query": "| `adx_users` | `adx_pwd_violations` | mvexpand violations | stats count by violations | sort - count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_17": {
      "type": "ds.search",
      "name": "Accounts not compliant with password rules",
      "options": {
        "query": "| `adx_users` | `adx_pwd_violations` | where isnotnull(violations) | eval n=mvcount(violations), privileged=if(is_privileged=1,\"YES\",\"no\"), last_logon=strftime(last_logon,\"%Y-%m-%d\") | sort - n, - pwd_age_days | table sam display_name violations pwd_age_days last_logon privileged ou",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_18": {
      "type": "ds.search",
      "name": "Passwords expired or expiring within 14 days",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND isnotnull(pwd_days_left) AND pwd_days_left<=14 | eval status=if(pwd_days_left<0,\"EXPIRED\",\"EXPIRING\"), days_overdue_or_left=pwd_days_left, last_logon=strftime(last_logon,\"%Y-%m-%d\") | sort pwd_days_left | table sam display_name status days_overdue_or_left pwd_age_days last_logon ou",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_19": {
      "type": "ds.search",
      "name": "Enabled vs disabled",
      "options": {
        "query": "| `adx_users` | eval state=if(is_disabled=1,\"Disabled\",\"Enabled\") | stats count by state",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_20": {
      "type": "ds.search",
      "name": "Password posture of enabled accounts",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 | eval posture=case(pwd_never_expires=1,\"Never expires\", pwd_age_days>`adx_max_pwd_age_days`,\"Older than policy age\", isnull(pwd_age_days),\"Unknown\", true(),\"Within policy age\") | stats count by posture",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_21": {
      "type": "ds.search",
      "name": "Password age of enabled accounts",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND isnotnull(pwd_age_days) | eval b=case(pwd_age_days<=30,\"1) 0-30 d\", pwd_age_days<=90,\"2) 31-90 d\", pwd_age_days<=180,\"3) 91-180 d\", pwd_age_days<=365,\"4) 181-365 d\", true(),\"5) > 1 year\") | stats count by b | sort b",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_22": {
      "type": "ds.search",
      "name": "Last logon of enabled accounts",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 | eval b=case(isnull(days_since_logon),\"6) Never / unknown\", days_since_logon<=7,\"1) <= 7 d\", days_since_logon<=30,\"2) 8-30 d\", days_since_logon<=90,\"3) 31-90 d\", days_since_logon<=180,\"4) 91-180 d\", true(),\"5) > 180 d\") | stats count by b | sort b",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_23": {
      "type": "ds.search",
      "name": "Password never expires - by OU (top 15, enabled)",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND pwd_never_expires=1 | stats count by ou | sort - count | head 15",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_24": {
      "type": "ds.search",
      "name": "Password never expires - enabled accounts",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND pwd_never_expires=1 | eval privileged=if(is_privileged=1,\"YES\",\"no\"), last_logon=strftime(last_logon,\"%Y-%m-%d\") | sort - is_privileged, - pwd_age_days | table sam display_name ou pwd_age_days last_logon privileged",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_25": {
      "type": "ds.search",
      "name": "Risky account configurations (enabled)",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 | eval risk=mvappend(if(pwd_not_required=1,\"PASSWD_NOTREQD\",null()), if(no_preauth=1,\"DONT_REQ_PREAUTH (AS-REP roastable)\",null()), if(trusted_for_delegation=1,\"Unconstrained delegation\",null()), if(pwd_never_expires=1 AND is_privileged=1,\"Privileged + password never expires\",null()), if(is_privileged=1 AND days_since_logon>`adx_stale_days`,\"Privileged + stale\",null())) | where isnotnull(risk) | table sam display_name risk ou pwd_age_days",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_26": {
      "type": "ds.search",
      "name": "Accounts expiring in the next 30 days",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND isnotnull(acct_expires) AND acct_expires>now() AND acct_expires<now()+30*86400 | eval days_left=round((acct_expires-now())/86400,0), expires=strftime(acct_expires,\"%Y-%m-%d\") | sort days_left | table sam display_name expires days_left ou",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_27": {
      "type": "ds.search",
      "name": "Enabled accounts past their expiry date",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND is_expired=1 | eval expired_on=strftime(acct_expires,\"%Y-%m-%d\") | table sam display_name expired_on ou",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_28": {
      "type": "ds.search",
      "name": "Disabled accounts that still belong to a privileged group",
      "options": {
        "query": "| `adx_users` | where is_disabled=1 AND is_privileged=1 | table sam display_name ou priv_groups",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_29": {
      "type": "ds.search",
      "name": "Stale enabled accounts (oldest logon first)",
      "options": {
        "query": "| `adx_users` | where is_disabled=0 AND days_since_logon>`adx_stale_days` | eval last_logon=strftime(last_logon,\"%Y-%m-%d\") | sort - days_since_logon | table sam display_name last_logon days_since_logon ou",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_30": {
      "type": "ds.search",
      "name": "Daily trend (needs the \"AD KPI Snapshot\" saved search enabled)",
      "options": {
        "query": "index=summary sourcetype=adx_kpi_snapshot | timechart span=1d max(never_expire_enabled) as \"Never expires (enabled)\", max(disabled) as \"Disabled\", max(stale_enabled) as \"Stale enabled\", max(locked) as \"Locked\"",
        "queryParameters": {
          "earliest": "-90d@d",
          "latest": "now"
        }
      }
    },
    "ds_31": {
      "type": "ds.search",
      "name": "Computers by operating system (top 10)",
      "options": {
        "query": "| `adx_computers` | where is_disabled=0 | stats count by os | sort - count | head 10",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_32": {
      "type": "ds.search",
      "name": "Stale enabled computers",
      "options": {
        "query": "| `adx_computers` | where is_disabled=0 AND days_since_logon>`adx_stale_days` | stats count",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    }
  },
